// Guards the shipped Maharashtra MSME questionnaire asset.
//
// assets/data/questionnaire.json is generated by
// backend/scripts/build_questionnaire.py from the officials' CSV. The app copy
// must be byte-identical to backend/catalog/questionnaire.json, which is the
// only source for questions.
import 'dart:convert';
import 'dart:io';

import 'package:flutter/services.dart';
import 'package:flutter_test/flutter_test.dart';

void main() {
  TestWidgetsFlutterBinding.ensureInitialized();

  test('app copy matches backend/catalog/questionnaire.json', () {
    final app = File('assets/data/questionnaire.json').readAsBytesSync();
    final backend =
        File('../backend/catalog/questionnaire.json').readAsBytesSync();
    expect(app, backend,
        reason: 'Run: python backend/scripts/build_questionnaire.py');
  });

  test('bundled asset loads and every field is complete in en/mr/hi',
      () async {
    final raw = await rootBundle.loadString('assets/data/questionnaire.json');
    final doc = jsonDecode(raw) as Map<String, dynamic>;
    expect(doc['languages'], ['en', 'mr', 'hi']);

    final fields = (doc['fields'] as List).cast<Map<String, dynamic>>();
    expect(fields, hasLength(26));
    expect(fields.map((f) => f['id']).toSet(), hasLength(26));

    for (final field in fields) {
      final question = field['question'] as Map<String, dynamic>;
      for (final lang in ['en', 'mr', 'hi']) {
        expect(question[lang], isNotEmpty, reason: '${field['id']} $lang');
      }
      final options =
          (field['options'] as List? ?? const []).cast<Map<String, dynamic>>();
      final values = options.map((o) => o['value'] as String).toList();
      expect(values.toSet(), hasLength(values.length),
          reason: '${field['id']} has duplicate option values');
      for (final option in options) {
        expect(option['value'], matches(RegExp(r'^[a-z0-9_]+$')));
        for (final lang in ['en', 'mr', 'hi']) {
          expect(option[lang], isNotEmpty,
              reason: '${field['id']}.${option['value']} $lang');
        }
      }
    }
  });
}
